changeSet.sql:
INSERT INTO pep_category (country_iso, code, label, kind, risk_class, sort_order, legal_reference)
VALUES ('CZ', 'CZ-EU', 'Tchèques exerçant une fonction européenne', 'EU', 1, 10, 'Liste de la Commission, JO C/2023/724');

INSERT INTO pep_function (category_id, label, institution, expected_holders)
SELECT c.id, f.label, f.institution, f.expected_holders
FROM pep_category c JOIN (
    SELECT 'CZ-EU' AS code, 'Député européen élu en Tchéquie' AS label, 'Parlement européen' AS institution, 21 AS expected_holders
    UNION ALL SELECT 'CZ-EU', 'Membre tchèque de la Commission européenne', 'Commission européenne', 1
) f ON f.code = c.code;
